mapper.sql:
WHERE DEL_YN = 'N'
     AND NOTICE_STTS_CD = #{status} 
     AND TARGET_TYPE_CD = #{target} 
 AND NOTIFY_SEND_YN = #{notifySend} 
   AND TITLE LIKE CONCAT('%', #{keyword}, '%')

mapper.update:
UPDATE NOTICE
   SET DEL_YN   = 'Y',
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN  = #{mdfrSn}
 WHERE NOTICE_SN = #{noticeSn}
   AND DEL_YN = 'N'
